// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address logger, bool status) public {
        // The owner of a freshly deployed C is address(0); only the owner may approve loggers.
        vm.prank(address(0));
        c.setApprovedLogger(logger, status);

        // From the logger's own account, a logging entry point must reflect the requested status.
        vm.prank(logger);
        bool ok = c.logFunded();

        // General rule: approval state observed behaviorally equals the stored status.
        assertTrue(ok == status, "approved logger behavior must match requested status");
    }
}
